local function _b64(d)
local b='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
d=d:gsub('[^'..b..'=]','')
return(d:gsub('.',function(x)
if x=='='then return''end
local r,f='',(b:find(x)-1)
for i=6,1,-1 do r=r..(f%2^i-f%2^(i-1)>0 and'1'or'0')end
return r
end):gsub('%d%d%d?%d?%d?%d?%d?%d?',function(x)
if#x~=8 then return''end
local c=0
for i=1,8 do c=c+(x:sub(i,i)=='1'and 2^(8-i)or 0)end
return string.char(c)
end))
end

local function _xor(a,c)
if bit32 and bit32.bxor then return bit32.bxor(a,c)end
local r,p=0,1
for _=0,31 do
local x,y=a%2,c%2
if x~=y then r=r+p end
a,c,p=(a-x)/2,(c-y)/2,p*2
end
return r
end

-- Stage 1: recover program stream
local function _S1()
local bin=_b64(table.concat(_P))
local o={}
for i=1,#bin do
local b=bin:byte(i)
local k=_K2[((i-1)%16)+1]
local m=((i-1)*9+3)%256
o[i]=_xor(_xor(b,k),m)
end
return o
end

-- Stage 2: VM interpreter (opcodes)
-- 1 PUSH  2 NOP  3 ACC
local function _VM(prog)
local out={}
local acc=0
local i=1
local n=#prog
while i<=n do
local op=prog[i]
local arg=prog[i+1] or 0
i=i+2
if op==1 then
out[#out+1]=arg
elseif op==2 then
-- nop
elseif op==3 then
acc=_xor(acc,arg)
end
end
return out
end

-- Stage 3: decrypt source
local function _DEC(enc)
local o={}
for i=1,#enc do
local x=enc[i]
local idx=i-1
local k0=_K[(idx%32)+1]
local k1=_K[((idx+11)%32)+1]
local k2=_K[((idx*3)%32)+1]
x=(x-k2)%256
x=_xor(x,k1)
x=(x-((idx*31)%256))%256
x=_xor(x,k0)
o[i]=string.char(x)
end
return table.concat(o)
end

-- opaque predicates
local _z=0
for _=1,7 do _z=_z+(_%3==0 and 1 or 0) end
if _z<0 then return end

local _prog=_S1()
local _enc=_VM(_prog)
local _src=_DEC(_enc)
local _fn,_err=(loadstring or load)(_src)
if not _fn then
error("[Montana] VM load fail: "..tostring(_err))
end
_fn()
